-- Темы 20, 18 и два вопроса о блокировках: уточнения по повторной проверке Codex (32 исправлений в 19 вопросах), ключи не меняются.
-- Источник: scripts/questions/064_codex_recheck_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Когда планировщик обычно выбирает соединение Nested Loop?', NULL, NULL, NULL, 'Какое сочетание условий обычно делает Nested Loop выгодным при соединении по равенству?'),
        ('question', 'Сортировка 100 000 строк по val в памяти заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', NULL, NULL, NULL, 'Сортировка 100 000 строк по val в памяти (одинаковые данные и work_mem, в обоих планах Sort Method: quicksort) заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?'),
        ('question', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Почему?', NULL, NULL, NULL, 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Какой механизм может объяснить такой результат?'),
        ('question', 'После загрузки большой таблицы ANALYZE вручную не выполняли. Когда автоочистка соберёт статистику при настройках по умолчанию?', NULL, NULL, NULL, 'После загрузки большой таблицы ANALYZE вручную не выполняли. При каком объёме изменений таблица станет кандидатом на автоматический ANALYZE при настройках по умолчанию?'),
        ('question', 'Таблица t (id int PRIMARY KEY, v int) без других ограничений и триггеров. Сеанс 1 выполнил BEGIN; UPDATE t SET v = 0 WHERE id = 1; и не завершил транзакцию. Какие команды сеанса 2 не будут ждать блокировок сеанса 1?', NULL, NULL, NULL, 'Таблица t (id int PRIMARY KEY, v int) без других ограничений и триггеров. Сеанс 1 выполнил BEGIN; UPDATE t SET v = 0 WHERE id = 1; и не завершил транзакцию. Каждая команда выполняется отдельно. Какие команды сеанса 2 не будут ждать блокировок сеанса 1?'),
        ('option', 'Что означает значение n_distinct = -1 для столбца в pg_stats?', 'Все значения в столбце разные', 'По статистике все значения различны', 'По оценке последнего анализа число разных значений равно числу строк. Отрицательное число — доля от числа строк, -1 означает 100 %.', NULL),
        ('option', 'Для столбца id в pg_stats correlation = 1. Что это значит?', 'Строки лежат в файле таблицы по возрастанию id', 'Статистика указывает на порядок строк по возрастанию id', 'По статистике последнего анализа порядок строк в файле совпадает с порядком id: соседние значения находятся на соседних страницах.', 'По статистике последнего анализа физический порядок строк в файле совпадает с порядком id. Это оценка, которая может устареть после изменений данных.'),
        ('option', 'Какое сочетание условий обычно делает Nested Loop выгодным при соединении по равенству?', 'Когда внешних строк мало, а у внутренней таблицы есть индекс', 'Внешних строк мало, внутри есть индекс по ключу соединения', 'Когда с одной стороны мало строк, а по ключу соединения в другой таблице есть индекс, для каждой внешней строки пара находится быстрым поиском по индексу.', NULL),
        ('option', 'Какое сочетание условий обычно делает Nested Loop выгодным при соединении по равенству?', 'Когда внутренняя таблица большая, а индекса по ключу соединения у неё нет', 'Оба набора велики, индекса по ключу соединения внутри нет', 'Без индекса на большой внутренней таблице вложенный цикл читал бы её целиком для каждой внешней строки; для таких данных обычно выбирают Hash Join. Nested Loop применяется и при равенстве, а если соединение задано только неравенством, он единственный вариант.', 'Без индекса по ключу большая внутренняя таблица читалась бы целиком для каждой внешней строки; при равенстве для таких данных обычно выбирают Hash Join. Nested Loop применяется и при неравенстве, а если соединение задано только неравенством, он единственный вариант.'),
        ('option', 'Что верно для соединения Hash Join?', 'Нужно хотя бы одно условие равенства, остальные проверяются отдельно', 'Нужно равенство для хеширования; возможны дополнительные фильтры', 'Хеш находит равные ключи; остальные условия соединения проверяет Join Filter.', 'В Hash Cond могут входить несколько пригодных для хеширования равенств. Условия соединения, не вошедшие туда, проверяются отдельно (Join Filter).'),
        ('option', 'Как работает Bitmap Heap Scan?', 'Берёт данные из индекса и к таблице не обращается', NULL, 'Так работает Index Only Scan.', 'Так описывают Index Only Scan, и то с оговоркой: он обходится без чтения таблицы только для страниц, отмеченных в карте видимости как all-visible. Bitmap Heap Scan всегда читает таблицу.'),
        ('option', 'Сортировка 100 000 строк по val в памяти (одинаковые данные и work_mem, в обоих планах Sort Method: quicksort) заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', 'Для правил ru_RU.utf8 сортировке понадобилось заметно больше work_mem', NULL, 'В условии обе сортировки идут в памяти, а объём памяти зависит от данных, а не от правил сравнения.', 'По условию work_mem одинаков и обе сортировки поместились в память; наблюдаемую разницу объясняет стоимость сравнений.'),
        ('option', 'Сортировка 100 000 строк по val в памяти (одинаковые данные и work_mem, в обоих планах Sort Method: quicksort) заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', 'С COLLATE "C" вместо сортировки используется индекс по val', NULL, 'Индекса по val нет, в обоих случаях есть узел Sort.', 'По условию выполнялась сортировка; замена её индексным доступом не показана.'),
        ('option', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Какой механизм может объяснить такой результат?', 'Исходный порядок строк сократил число дорогих сравнений при сортировке порций', 'Исходный порядок мог сократить число дорогих сравнений при сортировке порций', 'Порции из подряд идущих строк в большинстве были уже упорядочены. Быстрая сортировка PostgreSQL сначала проверяет, не упорядочен ли массив, и тогда завершает работу за один линейный просмотр этой порции; затем порции сливаются отдельно. Дорогих сравнений понадобилось намного меньше; на перемешанных данных это преимущество исчезло.', 'Если порция уже упорядочена, быстрая сортировка PostgreSQL проверяет это и завершает её одним линейным просмотром; затем порции сливаются отдельно. Это может компенсировать дополнительные затраты внешней сортировки; на перемешанных данных такого преимущества нет.'),
        ('option', 'Чем Index Scan отличается от Bitmap Heap Scan?', 'Bitmap Heap Scan может совмещать несколько индексов', 'План с Bitmap Heap Scan может объединять несколько индексов', 'Узлы BitmapAnd и BitmapOr объединяют карты разных индексов, и Bitmap Heap Scan читает страницы по итоговой карте: карты разных условий складываются до чтения таблицы.', NULL),
        ('option', 'Чем Index Scan отличается от Bitmap Heap Scan?', 'Index Scan по B-tree выдаёт строки в порядке индекса, сортировка может не понадобиться', 'Index Scan по B-tree может обеспечить порядок для ORDER BY', 'Порядок для ORDER BY даёт Index Scan по B-tree: строки выдаются в порядке индекса, поэтому отдельная сортировка может не понадобиться. Bitmap Heap Scan выдаёт строки в порядке страниц.', NULL),
        ('option', 'Почему по одному индексу нельзя понять, видна ли строка текущей транзакции?', 'В индексе нет xmin и xmax: они хранятся только в версиях строк', 'В индексных записях нет xmin и xmax версий строк', 'Номера транзакций xmin и xmax хранятся только в версиях строк таблицы, а в индексе их нет. Поэтому Index Scan проверяет видимость в таблице, а Index Only Scan сначала смотрит карту видимости и обращается к таблице, если отметки нет.', NULL),
        ('option', 'У сортировки с COLLATE "C" и с COLLATE "ru_RU.utf8" одинаковая оценка cost, хотя вторая выполняется почти в восемь раз дольше. Почему?', 'Статистика таблицы устарела, и число строк оценено неверно', NULL, 'Число строк оценено верно; расходится время, а не строки.', 'В условии нет сведений об ошибке оценки строк: расходятся оценка стоимости и время, а не число строк. Разницу объясняет цена сравнений, которую модель не учитывает.'),
        ('option', 'Процесс не использует HugeTLB. У него VmSize равен 439 МБ, VmRSS — 15 МБ, VmSwap — 1 МБ. Что из этого верно?', 'Виртуальная память — 439 МБ, из них 15 МБ в оперативной памяти и 1 МБ в свопе', 'VmSize — 439 МБ, RSS — около 15 МБ, приватные страницы в свопе — около 1 МБ', 'VmSize — зарезервированные адреса, VmRSS — страницы в оперативной памяти, VmSwap — приватные страницы в свопе.', 'VmSize — зарезервированные адреса, VmRSS — страницы в оперативной памяти (оценка), VmSwap — приватные анонимные страницы в свопе; своп разделяемой памяти сюда не входит.'),
        ('option', 'Процесс не использует HugeTLB. У него VmSize равен 439 МБ, VmRSS — 15 МБ, VmSwap — 1 МБ. Что из этого верно?', 'Виртуальная память — 439 МБ, и это утечка: оперативной памяти занято 15 МБ', 'VmSize — 439 МБ, RSS — около 1 МБ, приватные страницы в свопе — около 15 МБ', 'Адреса резервируются заранее, файлы отображаются целиком; сам по себе большой VmSize признаком утечки не является.', 'Значения RSS и свопа перепутаны: в оперативной памяти около 15 МБ, а в свопе около 1 МБ. Большой VmSize сам по себе не признак утечки: адреса резервируются заранее, файлы отображаются целиком.'),
        ('option', 'Процесс не использует HugeTLB. У него VmSize равен 439 МБ, VmRSS — 15 МБ, VmSwap — 1 МБ. Что из этого верно?', 'Виртуальная память — 16 МБ: сумма значений оперативной памяти и свопа', 'VmSize — 16 МБ, RSS — около 15 МБ, приватные страницы в свопе — около 1 МБ', 'Виртуальное адресное пространство — это VmSize, 439 МБ.', 'Виртуальное адресное пространство — это VmSize, 439 МБ: в него входят и зарезервированные адреса, а не только сумма RSS и свопа.'),
        ('option', 'Процесс не использует HugeTLB. У него VmSize равен 439 МБ, VmRSS — 15 МБ, VmSwap — 1 МБ. Что из этого верно?', 'Виртуальная память — 439 МБ, и вся она занята в оперативной памяти', 'VmSize — 439 МБ, RSS — около 439 МБ, приватные страницы в свопе — около 1 МБ', 'Столько адресов зарезервировано; в оперативной памяти находятся около 15 МБ.', NULL),
        ('option', 'Что верно для приватных страниц памяти дочернего процесса, созданного вызовом fork() в Linux, если общая память явно не подключалась?', 'Все приватные страницы родителя физически копируются в момент вызова fork', NULL, 'Это было бы медленно; копирование откладывается до первой записи.', 'fork не требует сразу копировать все приватные страницы: используется копирование при записи.'),
        ('option', 'Что верно для приватных страниц памяти дочернего процесса, созданного вызовом fork() в Linux, если общая память явно не подключалась?', 'Изменения, которые делает потомок, сразу становятся видны родителю', NULL, 'После записи у каждого своя копия страницы; видны только участки, явно подключённые как общая память.', 'Изменения приватных страниц изолированы: родитель не видит записи потомка и наоборот; видны только участки, явно подключённые как общая память.'),
        ('option', 'Что верно для приватных страниц памяти дочернего процесса, созданного вызовом fork() в Linux, если общая память явно не подключалась?', 'Приватные страницы разделяются до записи; при необходимости создаётся копия', NULL, 'Копирование при записи изолирует изменения приватных страниц: копия появляется, когда один из процессов пишет в страницу. Разделяемые отображения остаются общими после fork.', 'Копирование при записи изолирует изменения приватных страниц. При записи ядро создаёт отдельную копию, если страница ещё разделяется; уже исключительно принадлежащую процессу страницу можно использовать без копирования. Разделяемые отображения остаются общими после fork.'),
        ('option', 'У службы systemd (cgroup v2) заданы MemoryHigh=1700M и MemoryMax=2G, включён дисковый своп, для службы он не ограничен. Процессу службы нужно 3,6 ГБ активно используемой памяти. Что произойдёт?', 'Процесс будет завершён по лимиту MemoryMax в момент достижения 2 ГБ', NULL, 'Не сразу: сначала ядро пытается освободить память, в том числе вытеснением в своп. Жёсткий лимит и OOM возможны позже, если освободить память не удаётся.', 'Не сразу: MemoryMax ограничивает учтённую память службы. При нехватке ядро сначала пытается освободить память, в том числе вытеснением в своп (своп учитывается отдельно); если удержать расход в пределах лимита не удаётся, возможен OOM.'),
        ('option', 'У службы systemd (cgroup v2) заданы MemoryHigh=1700M и MemoryMax=2G, включён дисковый своп, для службы он не ограничен. Процессу службы нужно 3,6 ГБ активно используемой памяти. Что произойдёт?', 'Выше 1700 МБ ядро замедляет процесс и пытается освободить его страницы', NULL, 'MemoryHigh — мягкий порог: при его превышении процесс не завершается, а замедляется, и ядро пытается освободить его память; вытеснение в своп возможно, если есть подходящие страницы и место.', 'MemoryHigh — мягкий порог для всей службы: при его превышении процесс не завершается, а замедляется, и ядро пытается освободить память службы; вытеснение в своп возможно, если есть подходящие страницы и место.'),
        ('option', 'У службы systemd (cgroup v2) заданы MemoryHigh=1700M и MemoryMax=2G, включён дисковый своп, для службы он не ограничен. Процессу службы нужно 3,6 ГБ активно используемой памяти. Что произойдёт?', 'Служба будет перезапущена systemd, когда процесс достигнет 2 ГБ', NULL, 'Мгновенного перезапуска нет: сначала срабатывают мягкий порог и освобождение памяти.', 'MemoryMax не задаёт автоматический перезапуск. После завершения процесса поведение зависит от настроек службы, в частности Restart; в условии они не указаны.'),
        ('option', 'Процесс читает свою страницу, которая выгружена в своп на диске: копии страницы нет ни в оперативной памяти, ни в кеше свопа (сжатый кеш zswap не используется). Что произойдёт?', 'Возникнет страничное прерывание: ядро прочитает страницу из свопа с диска и продолжит работу', 'Ядро обработает страничное прерывание и прочитает страницу из свопа с диска', 'После чтения страницы с диска процесс продолжит работу. Пока страница читается, процесс ждёт диска; в ps он виден в состоянии D.', NULL),
        ('option', 'Сеанс ждёт блокировку. Что верно о поиске причины ожидания и об ограничении времени ожидания?', 'Заданный заранее lock_timeout = ''2s'' прервёт ожидание блокировки ошибкой через 2 с', 'Заданный заранее lock_timeout = ''2s'' ограничивает ожидание блокировки', 'При превышении лимита текущий оператор завершается ошибкой. Параметр задают до запроса: SET для сеанса или SET LOCAL внутри транзакции. Уже ждущий сеанс не выполнит новый SET, пока не закончится текущий запрос.', 'При превышении лимита текущий оператор завершается ошибкой. Лимит применяется отдельно к каждой попытке получить блокировку; более короткий statement_timeout может сработать раньше. Параметр задают до запроса: SET для сеанса или SET LOCAL внутри транзакции. Уже ждущий сеанс не выполнит новый SET, пока не закончится текущий запрос.'),
        ('explanation', 'В таблице t 100 000 строк, первичный ключ по id (индекс t_pkey), индекса по val нет. В каком из этих запросов в EXPLAIN ANALYZE обычно появится Sort Method: top-N heapsort?', NULL, NULL, 'top-N heapsort почти не расходует память, даже если строк много. Проверка: EXPLAIN (ANALYZE) SELECT * FROM t ORDER BY val LIMIT 10;', 'При небольшом LIMIT top-N heapsort хранит небольшой набор лучших строк вместо всего входа, поэтому расходует мало памяти. Проверка: EXPLAIN (ANALYZE) SELECT * FROM t ORDER BY val LIMIT 10;'),
        ('explanation', 'Параметр work_mem = 64MB. В непараллельном плане запроса две сортировки и одно хеш-соединение, hash_mem_multiplier по умолчанию. Чему равна сумма бюджетов памяти этих операций?', NULL, NULL, 'work_mem умножается на число операций в плане, на число параллельных процессов и на число одновременных запросов. Слишком большое значение при многих подключениях может увести сервер в своп или под OOM killer.', 'Каждая сортировка и хеш-операция имеет свой бюджет; для хеширования он учитывает hash_mem_multiplier. Параллельное выполнение и одновременные запросы могут увеличить суммарный расход, а фактический пик зависит от плана и других выделений памяти. Слишком большое значение при многих подключениях может увести сервер в своп или под OOM killer.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
